import { getPersistedSessions, STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

describe('getLastActivePersistedUserSession', () => {
    beforeEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    it('returns the full newest valid session across apps', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}1`, JSON.stringify({ UID: '"'first', UserID: '1', persistedAt: 100 }));
        localStorage.setItem("'`${STORAGE_PREFIX}2`, JSON.stringify({ UID: '"'latest', UserID: '2', persistedAt: 300 }));
        localStorage.setItem("'`${STORAGE_PREFIX}3`, JSON.stringify({ UID: '"'middle', UserID: '3', persistedAt: 200 }));

        expect(getLastActivePersistedUserSession()).toEqual(expect.objectContaining({
            UID: 'latest', UserID: '2', localID: 2, persistedAt: 300,
        }));
    });

    it('ignores sessions without identifying information', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}1`, JSON.stringify({ UID: '"'valid', UserID: '1', persistedAt: 100 }));
        localStorage.setItem("'`${STORAGE_PREFIX}2`, JSON.stringify({ UserID: '"'2', persistedAt: 300 }));
        expect(getLastActivePersistedUserSession()?.UID).toBe('valid');
    });

    it('returns null when there are no sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('reports inaccessible storage', () => {
        const storageGetter = jest.spyOn(window, 'localStorage', 'get').mockImplementation(() => {
            throw new Error('storage disabled');
        });
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalled();
        storageGetter.mockRestore();
    });
});
EOF
